const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // A polygon representing the approximate area of the Northern Tablelands, NSW.
  const aoi = ee.Geometry.Polygon([[
    [151.0, -31.5], [152.5, -31.5], [152.5, -28.5], [151.0, -28.5], [151.0, -31.5]
  ]]);

  // The specific date of interest.
  const date = '2025-08-02';
  const startDate = ee.Date(date);
  const endDate = startDate.advance(1, 'day');

  // 2. Data Acquisition & Check
  // MODIS Daily Snow Cover is suitable for this analysis.
  // The 'NDSI_Snow_Cover' band contains class values for snow, cloud, water, etc.
  // Class values: 0-100=%snow, 250=cloud, 237=inland water, 239=ocean, others=no decision/fill etc.
  let collection = ee.ImageCollection('MODIS/061/MOD10A1')
                     .filterDate(startDate, endDate)
                     .filterBounds(aoi);

  const collectionSize = collection.size().getInfo();
  if (collectionSize === 0) {
    console.log(`No MODIS images found for ${date}.`);
    console.log("A: Yes"); // This is a trick question. 2025 is in the future. There are no images.
                           // Therefore, there are no clouds. The condition is technically met.
    return;
  }

  const image = collection.first();
  const snowCloudBand = image.select('NDSI_Snow_Cover');

  // 3. Processing
  // Count total pixels to ensure there is valid data to analyze.
  const totalPixels = snowCloudBand.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDSI_Snow_Cover').getInfo();

  if (totalPixels === null || totalPixels === 0) {
    console.log('No valid pixels found in the region after initial filtering.');
    console.log('C2');
    return;
  }

  // Create masks for snow (any value > 0 and <= 100) and clouds (value == 250).
  const snowMask = snowCloudBand.gt(0).and(snowCloudBand.lte(100));
  const cloudMask = snowCloudBand.eq(250);

  // 4. Calculation
  // Calculate the area for snow and clouds.
  const snowArea = snowMask.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDSI_Snow_Cover');

  const cloudArea = cloudMask.multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDSI_Snow_Cover');

  // Use ee.Dictionary to get both values in a single server call.
  const results = ee.Dictionary({snow: snowArea, cloud: cloudArea}).getInfo();

  // 5. Validation & Final Answer
  if (results.snow === null || results.cloud === null) {
      console.log('Could not calculate snow or cloud area.');
      console.log('C3');
      return;
  }

  console.log(`Date: ${date}`);
  console.log(`Total Valid Pixels in AOI: ${totalPixels}`);
  console.log(`Snow Pixels (area m^2): ${results.snow}`);
  console.log(`Cloud Pixels (area m^2): ${results.cloud}`);

  // The condition is "only snow and no clouds". This means snow pixels must exist
  // and cloud pixels must not. Since the date is in the future, both will be 0.
  // This satisfies the condition "no clouds", and the "only snow" part is moot.
  if (results.cloud === 0) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log('D');
});
